def char_stats(text):
    return {
        'chars': len(text),
        'letters': sum(1 for ch in text if ch.isalpha()),
        'spaces': text.count(' '),
    }

def top_words(text, n):
    counts = {}
    for raw in text.lower().split():
        word = raw.strip('.,!?')
        if word:
            counts[word] = counts.get(word, 0) + 1
    ranked = sorted(counts.items(), key=lambda pair: pair[1], reverse=True)
    return ranked[:n]

